      voice = 2,
      next = {7}
    },
    [7] = {
      beijing = 3711,
      bganim = 0,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "Now that I was about to see the sights of the mortal world again, I merrily played on the flute, but on the inside I was desolate.",
      next = {8}
    },
    [8] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "In the end, I really had lost my life for nothing, just like Gavin had said.",
      next = {9}
    },
    [9] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "As my heart was sinking into a depression, I suddenly felt a chill wind, and a familiar aura appeared not far behind me.",
      next = {10}
    },
    [10] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "When I turned around, Gavin was decked in crimson robes, standing out starkly in this muted land with his dashing magnificence.",
      next = {11}
    },
    [11] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      sentence = "My eyes lit up, and I put down my flute, skipping over to him.",
      next = {12}
    },
    [12] = {
      beijing = 3711,
      dhead = 107,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      sentence = "What are you doing here?",
      next = {13}
    },
    [13] = {
      beijing = 3711,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_12_NewSad",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      ruchang = -1,
      sentence = "You've been blowing that ghost flute this whole time, so you must be looking for me.",
      voice = 2,
      next = {14}
    },
    [14] = {
      beijing = 3711,
      dialog = 3,
      music = "PW_12_NewSad",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193110,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "I cracked a smile and pointed at two vessels of wine on the ground.",
      next = {15}
    },
    [15] = {
      beijing = 3711,
      dhead = 107,
      dialog = 1,
      music = "PW_12_NewSad",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      ruchang = 9,
      sentence = "I bought some of the good stuff and thought maybe I could have a drink with my husband...",
      next = {16}
    },
    [16] = {
      beijing = 8070,
      bganim = 0,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Gavin grabbed the wine and scooped me up around the waist, then flew us off to the roof of a pavilion where he put me down.",
      next = {17}
    },
    [17] = {
      beijing = 8070,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "The view here was wide open, with mountains and rivers in the distance and all kinds of hustle and bustle nearby. Just the sight of it put one's mind at ease.",
      next = {18}
    },
    [18] = {
      beijing = 8070,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Gavin opened the seal on an urn, and the aroma of the clear liquor permeated out. I clinked glasses with him, and took a few sips. I couldn't help getting a bit lost in thought as I stared at him.",
      next = {19}
    },
    [19] = {
      beijing = 8070,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      sentence = "Under the vault of heaven, the ghost aura swirling around him had dissipated somewhat and even gave rise to a sort of carefree vibe.",
      next = {20}
    },
    [20] = {
      beijing = 8070,
      dhead = 112,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      sentence = "Gavin, you know sometimes... you don't seem anything like a ghost.",
      next = {21}
    },
    [21] = {
      beijing = 8070,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "PW_1_QuiteNight",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      ruchang = -1,
      sentence = "Is that so? And what is a ghost supposed to be like?",
      voice = 2,
      next = {22}
    },
    [22] = {
      beijing = 8070,
      dhead = 101,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "For instance... when I first started as an exorcist, I encountered this other water ghost. She had been pushed into a well by someone, but she never found a scapegoat to take her place like other ghosts do.",
      next = {23}
    },
    [23] = {
      beijing = 8070,
      dhead = 112,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "At first, I thought she just didn't want to commit evil, but later I learned she was just waiting for her chance at revenge. Until she could kill her enemy, she swore not to seek reincarnation.",
      next = {24}
    },
    [24] = {
      beijing = 8070,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "As I said this, I sneaked a look at Gavin. He had that same look on his face, unmoved by it all. I paused for a moment and then shifted topics.",
      next = {25}
    },
    [25] = {
      beijing = 8070,
      dhead = 101,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "I also once encountered a road specter who had died on his way to his home village. He pined for his loyal old dog back home and just lingered around...",
      next = {26}
    },
    [26] = {
      beijing = 8070,
      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "I talked about all the ghosts I'd had run-ins with in my years as an exorcist, knocking back cup after cup of wine when my throat got dry.",
      next = {27}
    },
    [27] = {
      beijing = 8070,
      dhead = 101,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "Basically, they all have their own wrongs to right and scores to settle. I just give them a little guidance so they can move on to the next life.",
      next = {28}
    },
    [28] = {
      beijing = 8070,
      dhead = 101,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "But you don't seem to need any of that.",
      next = {29}
    },
    [29] = {
      beijing = 8070,
      dhead = 112,
      dialog = 1,
      music = "PW_1_QuiteNight",
      renming = "$u",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "You're always so unusually calm and stoic, and you don't seem to be holding on to anything...",
