      dialog = 3,
      music = "PW_1_QuiteNight",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "Gavin just leisurely wiggled the wine bottle, and it filled up again with fine wine out of nowhere.",
