      renming = "Gavin",
      renwu = "npc",
      role1 = 4193000,
      role2 = 4193111,
      role3 = 4193207,
      role5 = 4193401,
      sentence = "You said I don't seem like a ghost, but if you ask me, you don't seem like an exorcist either.",
