      renwu = "npc",
      role1 = 4194000,
      role2 = 4194110,
      role3 = 4194210,
      role5 = 4194401,
      sentence = "I became an exorcist precisely so that these eyes of mine don't go to waste. When it comes to right and wrong, humans and ghosts should be equals to begin with.",
